func Test_ordersStatus_RoundTrip(t *testing.T) {
	cases := []struct {
		db int32
		pb orderv1.OrderStatus
	}{
		{1, orderv1.OrderStatus_ORDER_STATUS_PENDING},
		{2, orderv1.OrderStatus_ORDER_STATUS_RESERVING},
		{3, orderv1.OrderStatus_ORDER_STATUS_CHARGING},
		{4, orderv1.OrderStatus_ORDER_STATUS_CONFIRMING},
		{5, orderv1.OrderStatus_ORDER_STATUS_RELEASING},
		{6, orderv1.OrderStatus_ORDER_STATUS_CONFIRMED},
		{7, orderv1.OrderStatus_ORDER_STATUS_CANCELLED},
	}
	for _, c := range cases {
		if got := ordersStatusToProto(c.db); got != c.pb {
			t.Errorf("ToProto(%d) = %v, want %v", c.db, got, c.pb)
		}
		if got := ordersStatusToDB(c.pb); got != c.db {
			t.Errorf("ToDB(%v) = %d, want %d", c.pb, got, c.db)
		}
	}
}

